CREATE TABLE public.cms_members (user_id uuid PRIMARY KEY, role text NOT NULL CHECK (role IN ('owner','editor','sales')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cms_members TO authenticated; GRANT ALL ON public.cms_members TO service_role;
ALTER TABLE public.cms_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_self ON public.cms_members FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.cms_access(scope text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cms_members WHERE user_id=auth.uid() AND (role='owner' OR (scope='content' AND role='editor') OR (scope='leads' AND role='sales'))) $$;
GRANT EXECUTE ON FUNCTION public.cms_access(text) TO authenticated;
CREATE TABLE public.cms_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text UNIQUE NOT NULL, kind text NOT NULL DEFAULT 'page', draft jsonb NOT NULL DEFAULT '{}'::jsonb, published jsonb, state text NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, updated_by uuid);
GRANT SELECT,INSERT,UPDATE ON public.cms_documents TO authenticated; GRANT ALL ON public.cms_documents TO service_role;
ALTER TABLE public.cms_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_documents_editor ON public.cms_documents FOR ALL TO authenticated USING(public.cms_access('content')) WITH CHECK(public.cms_access('content'));
CREATE TABLE public.cms_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.cms_documents(id), snapshot jsonb NOT NULL, action text NOT NULL, author_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.cms_revisions TO authenticated; GRANT ALL ON public.cms_revisions TO service_role;
ALTER TABLE public.cms_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_revision_read ON public.cms_revisions FOR SELECT TO authenticated USING(public.cms_access('content'));
CREATE TABLE public.cms_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cms_audit TO authenticated; GRANT ALL ON public.cms_audit TO service_role;
ALTER TABLE public.cms_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_audit_read ON public.cms_audit FOR SELECT TO authenticated USING(public.cms_access('content') OR public.cms_access('leads'));
CREATE TABLE public.cms_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), url text NOT NULL, storage_path text, title text NOT NULL, alt_ar text NOT NULL DEFAULT '', alt_en text NOT NULL DEFAULT '', width integer, height integer, source text NOT NULL DEFAULT '', approval text NOT NULL DEFAULT 'draft', locked boolean NOT NULL DEFAULT false, focal_x integer NOT NULL DEFAULT 50, focal_y integer NOT NULL DEFAULT 50, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.cms_media TO authenticated; GRANT ALL ON public.cms_media TO service_role;
ALTER TABLE public.cms_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_media_editor ON public.cms_media FOR ALL TO authenticated USING(public.cms_access('content')) WITH CHECK(public.cms_access('content'));
CREATE TABLE public.cms_config (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cms_config TO authenticated; GRANT ALL ON public.cms_config TO service_role;
ALTER TABLE public.cms_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_config_admin ON public.cms_config FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.lead_rate_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
GRANT ALL ON public.lead_rate_limits TO service_role;
ALTER TABLE public.lead_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_lead_limit(rate_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.lead_rate_limits(key) VALUES(rate_key) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN lead_rate_limits.window_start<now()-interval '15 minutes' THEN 1 ELSE lead_rate_limits.attempts+1 END,window_start=CASE WHEN lead_rate_limits.window_start<now()-interval '15 minutes' THEN now() ELSE lead_rate_limits.window_start END RETURNING attempts INTO n; RETURN n<=5; END $$;
REVOKE ALL ON FUNCTION public.consume_lead_limit(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_lead_limit(text) TO service_role;
ALTER TABLE public.contact_requests ADD COLUMN interest text, ADD COLUMN request_type text NOT NULL DEFAULT 'demo', ADD COLUMN job_role text, ADD COLUMN industry text, ADD COLUMN utm jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN referrer text, ADD COLUMN consent boolean NOT NULL DEFAULT false, ADD COLUMN assigned_to uuid, ADD COLUMN notification_status text NOT NULL DEFAULT 'not_configured', ADD COLUMN notification_recipient text, ADD COLUMN notification_error text;
CREATE POLICY sales_read_leads ON public.contact_requests FOR SELECT TO authenticated USING(public.cms_access('leads'));
CREATE POLICY sales_update_leads ON public.contact_requests FOR UPDATE TO authenticated USING(public.cms_access('leads')) WITH CHECK(public.cms_access('leads'));
CREATE OR REPLACE FUNCTION public.audit_cms_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.cms_revisions(document_id,snapshot,action,author_id) VALUES(NEW.id,to_jsonb(NEW),CASE WHEN TG_OP='INSERT' THEN 'create' WHEN NEW.published IS DISTINCT FROM OLD.published THEN 'publish' ELSE 'save' END,auth.uid()); INSERT INTO public.cms_audit(actor_id,action,entity,entity_id) VALUES(auth.uid(),TG_OP,'document',NEW.id::text); RETURN NEW; END $$;
CREATE TRIGGER cms_document_history AFTER INSERT OR UPDATE ON public.cms_documents FOR EACH ROW EXECUTE FUNCTION public.audit_cms_document();
CREATE INDEX cms_revisions_document ON public.cms_revisions(document_id,created_at DESC);
CREATE INDEX leads_recent ON public.contact_requests(created_at DESC);
CREATE INDEX cms_documents_kind ON public.cms_documents(kind);
